id='cn-ancient-08-01-ming-governance';a='ming-court-work-v1'
c=base(id,'明朝的事情，怎样从意见变成行动？','宫里批好一份文书，河边的水闸就会自己修好吗？小伙伴去找提意见、作决定和实际做事的人。','明代皇帝掌握重要决定，后来内阁帮助拟意见；决定落到实际事情上，还需要官员和劳动者办理。','明代皇帝、内阁与实际办事的人',[M,G,U],'明初1380年废丞相与后来内阁形成票拟分开，不压成同一年。三扇故事窗表示不同地点的虚构角色分工，不是洪武在北京办公或真实奏章。批红也可能由司礼监代行，不把皇权集中等同于决策必然正确。','有意见、有决定，还要有人真正做事。')
c['steps']=[time_ming('明朝1368年建立，起初都城在南京。后来北京宫殿1420年建成。照片是今天的故宫，建筑还经历了后来的重建。宫里的事情怎样传到各地？','1368年建立的是哪个朝代？','先到明朝，再看不同的人怎样办事。','清朝在后，1368年建立的是明朝。','听听制度先后怎样变化',[M,U],'明朝1368年建立，我们先到明朝。'),step('先后变化的办事办法','明初皇帝废除了丞相。后来，内阁大臣帮助拟意见，重要决定仍由皇帝掌握。图里用三扇故事窗，分别看提意见、作决定与河边干活；它们不是同一间屋子。','文书里的意见，怎样变成行动？','纸上的决定，还要有人去办理。','可以再听一遍。','先找提意见，再找作决定',[M,G],kind='look-listen',asset=a,display='先有废丞相，后来内阁逐渐发展。\n提意见、作决定、实际办理，各有不同。'),step('三扇窗，三种工作','内阁可以先拟出处理意见，皇帝决定是否采用。再找找河边的人，他们做的工作又有什么不同？','哪里正在写处理意见？','意见与决定不同，还要接上实际办理。','看看笔和文书旁的工作。','纸上决定以后呢',[G],kind='scene-find',asset=a),step('水闸还没有修好','文书已经批下来了，水闸却还没有修好。要把纸上的决定落实到眼前的事情上，现在最需要哪一组人接着做？','水闸还没修好，该谁接着做？','河边的人动手办理，纸上决定才落到实处。','整理文书有用，但不能代替现场修理。','把几种工作连起来',[G,M],options=[card('到河边实际修理的人',a,[1080,80,456,510,1536,1024],True),card('继续在桌边拟意见的人',a,[20,75,440,430,1536,1024],False)],asset=a),step('权力集中，也离不开许多人','明代皇帝掌握重要决定，内阁提供意见，各地还有官员和劳动者具体办理。不同的人有不同工作。皇帝作了决定，并不等于事情已经做好，也不等于每次决定都正确。','从意见，到决定，再到实际办理','把实际做事的人也放进历史里。','可以再听一遍。','带着办事的发现回家',[G,M],kind='look-listen',asset=a,display='提意见 → 作决定 → 实际办理。\n决定写下来了，事情还要继续做。')]
c['steps'][0]['inspection']=ins('forbidden-city-hall-current-photo','这是今天的太和殿区域，有现代游客。北京宫殿始建于明代，眼前太和殿的形制来自清代重建；不能拿这张照片当明初办公现场。',[U,R],300,'故宫现状 · 太和殿为清代重建形制')
scene_find(c['steps'][2],[('draft','左边桌上拟意见的工作',.06,.27,.24,.18),('decide','中间批阅文书的工作',.37,.27,.25,.19)],[('draft','哪里正在写处理意见？','draft','大臣先拟意见，供皇帝决定是否采用。','这里在作决定，再找左边拟意见的桌子。','再找作决定的工作'),('decide','哪里表示皇帝在决定是否采用？','decide','皇帝掌握决定；实际办理还在后面。','先拟意见的人，还不等于作最后决定。','看看河边还要做什么')])
