id='cn-ancient-08-02-zheng-he';a='ming-voyage-talk-v1'
c=base(id,'郑和的船队，怎样与远方交往？','石碑从南京走到今天的斯里兰卡，留下三种文字。小伙伴去看远航怎样准备，又怎样与不同语言的人交流。','明代郑和多次率船队远航，开展对外交往。补给让船队走远，语言沟通帮助交流；三语碑留下了联系的证据。','郑和与船队中的不同工作者',[M,Z],'1405—1433七次远航；三语碑1409年南京刻制，第三次航行带至锡兰，不把刻制与立碑日期混写。三段文字宗教对象及内容不同，不是逐字翻译。故事图为印度洋港口教学情境，不是特定斯里兰卡城市复原或某次会面记录；不把所有远航活动概括为没有冲突。','船能走远，也要把意思说清楚。')
c['steps']=[time_ming('这块石碑与郑和船队有关。它1409年在南京刻好，第三次远航时被带到锡兰，也就是今天的斯里兰卡。那时是明朝，船队正在与远方交往。','跟着这块石碑，去哪个朝代？','到明朝，看看船队怎样与远方联系。','清朝在后，郑和远航在明朝。','听听为什么要远航',[Z],'郑和在明朝率船队远航，这块石碑也跟着出海。'),step('远航不只是把船开出去','1405到1433年，郑和七次率船队远航，代表明朝开展交往，也进行物品与文化交流。船要准备食物和淡水；到港以后，还需要懂语言的人帮助彼此说明来意。','准备下一程，也要说清来意','补给与沟通，帮助远航和交往。','可以再听一遍。','找找船队的两种工作',[M,Z],kind='look-listen',asset=a,display='七次远航，跨过许多年。\n船上要补给，到港要沟通。'),step('先看补给，再看语言','故事里的船停靠港口。左边有人搬运补给，右边的人正帮双方理解彼此的话。小伙伴先找补给，再找语言沟通。','哪里正在准备船上的补给？','走得远，也要与人说得明白。','看看装运物资和交谈分别在哪里。','已经到港，该先找谁',[Z],kind='scene-find',asset=a),step('到了港口，怎样说明来意','补给已经安排好，船队现在想向港口的人说明来意。双方说的语言不同，此刻先请谁帮忙，才能开始交流？','要让双方听懂，该请谁帮忙？','懂双方语言的人，帮助彼此说明意思。','补给支持航行；现在需要帮助沟通。','回看石碑留下的联系',[Z],options=[card('请懂语言的人帮助交流',a,[865,200,660,530,1536,1024],True),card('请搬运补给的人继续装船',a,[15,100,620,420,1536,1024],False)],asset=a),step('三种文字，留下远方的联系','这块碑上有汉文、泰米尔文和波斯文，三段内容并不相同。真实的碑，帮助我们了解船队与远方的联系。小伙伴把补给、沟通和留下的材料一起记进手册。','石碑给历史留下可核对的线索','补给让船走远，沟通让交往继续。','可以再听一遍。','带着远航的发现回家',[Z],kind='look-listen',asset=a,display='石碑留下三种文字。\n它们不是逐字相同的翻译。')]
c['steps'][0]['inspection']=ins('galle-trilingual-stele-current-photo','这是科伦坡国立博物馆保存的原碑照片。反光使小字看不清，先观察碑的整体；三种文字和历史用途由资料帮助说明。',[Z],335,'明代 · 1409年南京刻制 · 原碑现状')
scene_find(c['steps'][2],[('supply','左边装运补给的地方',.035,.26,.36,.23),('talk','右边帮助双方交谈的人',.68,.39,.16,.24)],[('supply','哪里正在准备船上的补给？','supply','淡水与食物，让远航有了必要准备。','他们正在交谈，再找装运物资的地方。','再找帮助双方交谈的人'),('talk','谁在帮助双方听懂彼此的话？','talk','语言沟通，帮助说明来意和交流。','这里是补给，再找两方之间的人。','船已到港，先请谁帮忙')])
c['steps'][4]['inspection']=ins('galle-trilingual-stele-current-photo','同一块碑有三种文字，但内容不是逐字相同的翻译。它与郑和船队有关，不是故事插画里的某个人留下的亲笔记录。',[Z],300)
