id='cn-ancient-08-04-economy-knowledge-culture';a='ming-craft-observation-v1'
c=base(id,'宋应星为什么把工匠写进书？','砖怎么做，布怎么织？《天工开物》把许多人的生产手艺写进图文。小伙伴也试着观察一次，再留下记录。','宋应星整理生产技术，1637年刊行《天工开物》。工匠长期积累的经验，经观察和图文记录，可以让更多人了解。','宋应星与长期积累经验的工匠',[T,SCAN,'NMC-TIANGONG-KAIWU'],'书影为1637宋应星自刻本第3册PDF第7页，砖瓦图不当织布图。故事中的织布观察为教学虚构，不是作者某次亲访记录。国图分上中下三卷、十八篇，国博18卷为不同口径，儿童不考卷数。作者整理知识，不是书中所有技术的发明人。','看见怎样做，再把方法留下来。')
c['steps']=[time_ming('这页古书把做砖的工序画出来了。它来自1637年刊行的《天工开物》，作者宋应星生活在明朝。书里还记录种粮、织布等许多生产手艺。','1637年的这本书，属于哪一朝？','明朝的宋应星，把生产手艺整理成书。','清朝在后，这本书初刊在明朝。','看看为什么要记录手艺',[T,SCAN],'《天工开物》初刊于明朝1637年。'),step('普通人的手艺，也值得记录','衣服和饭食，都离不开劳动。宋应星把许多生产知识整理成《天工开物》，用文字和图画说明。今天的小伙伴也来练习：看清一位工匠怎样织布，再把过程记下来。','手艺从劳动中来，图文把它留下','工匠的经验，是这本书的重要内容。','可以再听一遍。','找找操作与记录',[T],kind='look-listen',asset=a,display='不是只看做好的东西。\n还要看，人们怎样把它做出来。'),step('织布的人，记录的人','织布的人操作织机，旁边的人把看到的方法画下来。先找正在做的动作，再找把动作留下来的记录。','哪里正在把线织成布？','操作产生经验，记录帮助人们了解。','看看织机和书页分别在哪里。','要了解方法，应该先看什么',[T],kind='scene-find',asset=a),step('漂亮的布，是怎样织成的','小伙伴已经看见一卷漂亮的布，现在想知道线怎样变成布。为了把方法讲清楚，还需要观察哪一处？','要了解织法，接着看哪一处？','观察织机怎样工作，才看得见过程。','成品能看颜色和纹样，还看不到怎样织。','把手艺的发现带进书里',[T],options=[card('观察织机正在怎样工作',a,[20,95,640,540,1536,1024],True),card('只看已经织好的布卷',a,[55,740,715,205,1536,1024],False)],asset=a),step('一本书，许多人的经验','《天工开物》记录了许多生产技术。宋应星整理这些知识，背后还有工匠长期的实践。图文能帮助后来的人了解方法，但学会手艺还需要亲自练习、继续改进。','把劳动经验写进历史','作者的整理，与工匠的劳动都值得记住。','可以再听一遍。','带着手艺的发现回家',[T],kind='look-listen',asset=a,display='许多工匠的经验，整理成图文。\n阅读能了解，手艺还要练习。')]
c['steps'][0]['inspection']=ins('tiangong-1637-brickmaking','看看古书怎样把做砖的工具和工序画下来。这是真实的1637年刊本书影，不要求认出古字。后面的织布图，是另一种工艺的教学故事。',[T,SCAN],315)
scene_find(c['steps'][2],[('weave','左边织机上的操作',.04,.36,.38,.24),('record','右边画下方法的书页',.61,.30,.25,.16)],[('weave','哪里正在把线织成布？','weave','手艺来自实际操作和积累。','那里在记录，再找织机上的工作。','再找把方法记录下来的地方'),('record','哪里把看到的方法留在了纸上？','record','图文可以帮助后来的人了解过程。','织机正在工作，记录在另一边的纸上。','还想看清怎样织布')])
done(c,a,'ming-qing-economy-knowledge-culture',['先指织机的工作，再指记录，告诉家人两者怎样连接。','请家人慢慢演示叠一张纸，你先看，再画两个步骤说明怎样做。'],'使用安全日常动作体验观察与记录；不把古代技术书作为未经验证的医疗或工艺操作指南。')
# 4 屋脊小兽
id='cn-ancient-08-06-forbidden-city-roof-beasts';a='ming-roof-learning-v1'
c=base(id,'故宫屋脊的小兽，只是装饰吗？','抬头看太和殿，小兽沿屋脊排着队。小伙伴先看真照片，再用小模型看看：它们和屋顶的固定处有什么关系？','宫殿屋脊小兽兼有装饰与历史构件用途，也体现建筑礼制。明代始建的宫殿经历重建，现存太和殿是清代形制。','明清宫殿的工匠与今天的观察者',[R,Y,U],'1420年明代奉天殿始建，现太和殿为康熙1695年起重建后的形制（1697竣工）；现存十兽不当明代原物。骑凤仙人不计十兽，后面的大构件也不计。模型只说明一种旧做法的遮护固定处与装饰，不代表每座屋顶同样构造或现代工程指导。','小兽有用途，建筑也有自己的历史。')
c['steps']=[time_ming('北京宫殿在明朝1420年建成，后来多次维修重建。照片里的太和殿，是清代重建后的形制。我们先回到明朝建宫殿的时候，再看今天留下的小兽。','北京宫殿1420年建成，在哪一朝？','从明代始建，再看到清代重建后的样子。','清代重建在后，1420年建成在明朝。','听听小兽为什么上屋顶',[R,U],'北京宫殿1420年在明朝建成，今天太和殿则经历清代重建。'),step('小兽像帽子，也装点屋脊','古代有一种屋脊做法，用兽形构件遮护固定瓦的地方，又让屋顶好看。太和殿是举行大典的地方，小兽的安排也有礼制意义。今天我们用模型看一看，不爬上真的屋顶。','看看固定处，再看看小兽','实用、装饰和建筑规矩，都留下了历史。','可以再听一遍。','去真照片里找小兽',[R,Y],kind='look-listen',asset=a,display='小兽能装点屋脊，也曾遮护固定处。\n宫殿的安排，还有礼制意义。'),step('照片里，谁在队伍前面','照片最前面是骑凤仙人，后面才是十只走兽。仙人雕像不算走兽。先找队伍前面的仙人，再找跟在后面的一排小兽。','先找骑在凤凰上的仙人雕像','仙人与走兽，是不同的屋脊装饰。','先看队伍最前面，再看后面的一排。','用模型看它怎样盖住固定处',[R,Y],kind='scene-find',asset='taihe-hall-ten-roof-beasts-current-photo'),step('给固定处戴上一顶小兽帽','这个剖面模型露出屋脊上的固定处。把小兽罩上去，看看底座怎样落到屋脊上。这只是用来理解一种旧做法，不是所有屋顶内部都这样。','小兽怎样罩住这个固定处？','盖住固定处，也给屋脊添上装饰。','再看看固定处在哪里。','把用途和历史连起来',[Y,R],kind='history-lab',asset=a),step('同一座宫殿，也会发生变化','明代建起的宫殿，后来经历维修与重建。今天太和殿的小兽，让我们观察清代重建后的形制。看建筑，要问它怎样使用，也要问眼前的部分来自哪个时候。','看用途，也看它来自哪个时候','不要把今天看见的，都当成最初的样子。','可以再听一遍。','带着屋脊的发现回家',[R,U,Y],kind='look-listen',asset=a,display='明代始建，后来又重建。\n今天的样子，不全是最初的样子。')]
c['steps'][0]['inspection']=ins('forbidden-city-hall-current-photo','先看太和殿整座建筑，再到相册看屋脊。北京宫殿明代建成，眼前太和殿的形制来自清代重建。',[R,U],290,'明代始建 · 太和殿为清代重建形制');c['steps'][0]['inspection']['openAlbum']=True
# Normalized hotspots follow this explicit crop; full original remains in the evidence viewer.
scene_find(c['steps'][2],[('rider','队伍前面的骑凤仙人',.845,.07,.14,.32),('beasts','仙人后面的一排走兽',.02,.14,.81,.49)],[('rider','先找骑在凤凰上的仙人雕像','rider','前面的仙人雕像，不算在十只走兽里。','这一排是走兽，再看队伍最前端。','再找仙人后面的一排走兽'),('beasts','再找仙人后面的一排走兽','beasts','这是走兽队伍，我们不必背下每个名字。','仙人在前面，走兽排在它的后方。','用模型看看构件的用途')],label='实物照片',ratio=2.5)
c['steps'][2]['interaction']['imageCrop']={'x':800,'y':930,'width':3000,'height':1200,'sourceWidth':4000,'sourceHeight':3000}
c['steps'][2]['inspection']=ins('taihe-hall-ten-roof-beasts-current-photo','现在看的是真实照片的一部分。点开可以看原图。骑凤仙人在最前，后面是十只走兽；更大的屋脊构件不混在这十只里面。',[R,Y],320)
c['steps'][3]['interaction']['lab']={'kind':'roof','stages':[{'label':'把小兽罩在固定处上','narration':'小兽的底座落到屋脊上，像帽子一样罩住固定处，也装饰了屋顶。'}]}
c['photoAlbum']={'id':'taihe-roof-context','title':'从整座太和殿看到屋脊','label':'看看整座建筑与屋脊细节','photos':[]}
for aid,label,period,obs,narr in [('forbidden-city-hall-current-photo','整座太和殿','明代始建 · 清代重建形制 · 2009年照片','先看宫殿，再找屋顶的四个角。','太和殿用于举行盛大典礼。今天看到的形制来自清代重建，照片还拍到了现代游客。'),('taihe-hall-ten-roof-beasts-current-photo','屋脊小兽','清代重建形制 · 2014年照片','骑凤仙人在前，后面跟着走兽。','这张照片让我们仔细看仙人与走兽。十只走兽不含最前的骑凤仙人，也不含后面的大构件。')]:
 ar=AR[aid];c['photoAlbum']['photos'].append({'assetId':aid,'title':ar['title'],'label':label,'period':period,'observation':obs,'narration':narr,'sourceIds':[R,Y],'sourceLinks':[link(R),link(Y),{'title':'照片与许可','url':ar['sourcePage']}],'boundary':ar.get('boundary',ar['notes'])})
done(c,a,'ming-forbidden-city-roof-beasts',['先在真图里指出仙人和走兽，再说出小兽曾有的一种用途。','把一张纸轻轻盖在桌上的小积木上，演示“遮护”，再说这只是学习模型。'],'礼制讨论限建筑用途与构件规制，不给人物或人群排高低；不把小兽神话功能当物理事实。')
# 5 西游记
id='cn-ancient-08-07-journey-west-print';a='ming-novel-bookshop-v1'
c=base(id,'《西游记》怎样从书页走到读者手里？','真古书里画着孙悟空，但孙悟空不是历史上的真人。小伙伴走进书坊故事，看看图文怎样印出来、装成书。','明代小说《西游记》把历史素材化为文学想象。书坊印出图文、整理装订，让故事有了可以流传的书本。','《西游记》与明代书坊的劳动者',[J],'1592世德堂本为明代小说图像，不是唐代玄奘现场。孙悟空只在书页想象中出现，不列入真实西行队伍。书坊图不声称复原某家1592年作坊；印刷传播不等于当时人人识字或人人拥有书。','故事有想象，书本也有做出来的过程。')
c['steps']=[time_ming('这是真正的1592年《西游记》书页，刊行在明朝。画里是孙悟空与铁扇公主的故事。小说借用了更早的历史素材，却加入许多想象，不能当真实旅行记录。','1592年这本小说，刊行在哪一朝？','明朝的小说刊本，讲了充满想象的故事。','清朝在后，这个刊本在明朝。','走进印书的故事',[J],'这本《西游记》刊行在明朝1592年。'),step('有了故事，还要把书做出来','故事写好以后，要刻版、印出图文，再把纸页整理装订。今天的小伙伴来到一个书坊故事里：孙悟空留在书页上，印书和装订的人正在忙。','一页页故事，怎样成为一本书？','故事传播，也靠印书和装订的工作。','可以再听一遍。','找找印书和装订',[J],kind='look-listen',asset=a,display='刻版、印图文，再整理装订。\n孙悟空在故事里，工匠在做书。'),step('左边印，右边订','左边的工匠正在把刻版上的图文印到纸上，右边的工匠把纸页整理成册。先找印书，再找装订。','哪里把版上的图文印到纸上？','一页页印出来，再整理成书。','看看纸页是正被印，还是正在装订。','印好的纸页接着去哪儿',[J],kind='scene-find',asset=a),step('纸页已经印好，怎样变成书','图文已经印好了，小伙伴手里还是一叠分开的纸页。要把这些页变成一本便于翻看的书，下一步找谁？','一叠纸页，要请谁接着处理？','整理、装订以后，纸页才能成册翻看。','这里能继续印页，眼前的纸页还需要装订。','把故事和历史分开记',[J],options=[card('请整理装订的人接手',a,[950,65,550,430,1536,1024],True),card('请印书的人再印一张',a,[85,80,660,390,1536,1024],False)],asset=a),step('读小说，也看书本的历史','《西游记》是小说，孙悟空的本领来自想象。真实的明代书页，则能告诉我们故事曾怎样被印出来。把文学想象与历史材料分开，读故事会多一双观察的眼睛。','想象的角色，真实的古书','故事好看，书本也有可追问的历史。','可以再听一遍。','带着古书的发现回家',[J],kind='look-listen',asset=a,display='孙悟空是小说角色。\n1592年的刊本，是历史材料。')]
c['steps'][0]['inspection']=ins('journey-west-shidetang-1592-print','看同一幅故事插图怎样跨在两页上。这是1592年明代刊本，不是玄奘西行现场。图里的孙悟空和铁扇公主属于小说。',[J],325,'明代1592年 · 世德堂本小说插图')
scene_find(c['steps'][2],[('print','左边印图文的工作',.12,.25,.32,.19),('bind','右边整理装订的工作',.63,.27,.28,.20)],[('print','哪里把版上的图文印到纸上？','print','这一步把图文印成可以整理的书页。','那里在装订，再找纸压在刻版上的地方。','再找整理装订的工作'),('bind','哪里把分开的纸页整理成书？','bind','纸页装成册，读者才能连着翻看。','那里在印页，再找正在整理成册的地方。','这些印好的纸页接着怎么办')])
done(c,a,'ming-journey-west-print',['指真书页说“这是明代留下的刊本”，再指孙悟空说“这是小说角色”。','把两张自己画的故事纸按顺序叠好，请家人帮忙做成小册子，体验成册与翻页。'],'关注小说与史料区别、印装劳动与传播；不用危险装订工具，不把西游记当唐代旅行实录。')
# 6 徐霞客
id='cn-ancient-08-08-xu-xiake-notebook';a='ming-travel-observation-v1'
c=base(id,'跟徐霞客学会看山水、留记录','走过一座桥，看见一条河，怎样让后来的人也知道你的发现？小伙伴从徐霞客的游记出发，练习看清楚、记具体。','明代徐霞客长期旅行、观察山川并留下记录；后人整理成游记。具体的观察和记录，帮助人们认识地理。','徐霞客与后来整理游记的人',[X],'后世画像不是生前照片。旅行观察图是今天的教学练习，现代线圈本与铅笔不当徐霞客原物，角色不当其肖像。没有编造徐霞客在此桥的亲历日记；游记由后人整理，不是一趟旅行当场完成。','看得仔细，记得具体，发现才留得下来。')
c['steps']=[time_ming('徐霞客生活在明朝，长年旅行，仔细观察山川并留下记录。这幅是后人画的肖像，不是照片。小伙伴想学他的办法：走到眼前，认真看，再记下来。','跟着徐霞客，来到哪一朝？','明代的徐霞客，用旅行和记录认识山川。','清朝在后，徐霞客生活在明朝。','听听游记怎样留下来',[X],'徐霞客是明代的旅行者，我们从明朝出发。'),step('不是只说这里真漂亮','徐霞客看山、水和道路，也记录具体所见。他一生留下许多旅行记录，后来由他人整理成游记。今天我们做一次自己的观察练习：桥在哪里，水从哪里经过？','观察具体的东西，留下具体的记录','游记里的地理认识，来自长期观察。','可以再听一遍。','看看观察与记录怎样配合',[X],kind='look-listen',asset=a,display='今天的练习：先观察，再记录。\n徐霞客的记录，后来由他人整理成书。'),step('一边看现场，一边留记录','这是今天的小伙伴在做练习，不是徐霞客的真实旅程。左边观察河与桥，右边把所见画进本子。找到两种动作，看它们怎样互相配合。','哪里正在观察眼前的河与桥？','看现场，再留下可回看的线索。','看看目光指向现场，还是笔落在纸上。','离开前还需要留下什么',[X],kind='scene-find',asset=a),step('马上要走，怎样把发现留下','小伙伴已经看清河流从桥下经过，现在要离开了。怎样让没来的人也了解这个发现，而不只听到一句“真漂亮”？','离开之前，怎样留下具体发现？','画下桥与河的位置，别人就有线索可看。','继续看有帮助，但离开后还需要记录。','把记录带给后来的人',[X],options=[card('画下桥与河的位置',a,[970,550,480,365,1536,1024],True),card('继续站在岸边看一会儿',a,[0,50,610,500,1536,1024],False)],asset=a),step('给后来的人留下观察线索','徐霞客长年积累的记录，后来被整理成《徐霞客游记》，留下认识山川的材料。记录也有时代条件和局限。今天我们可以学他认真观察，却不能把练习本说成古人的原稿。','观察、记录，还要后来整理','自己的发现，说清看见了什么。','可以再听一遍。','带着观察的方法回家',[X],kind='look-listen',asset=a,display='长期观察，留下记录。\n后人整理，让发现可以继续被阅读。')]
c['steps'][0]['inspection']=ins('xu-xiake-later-portrait-artwork','这幅是后世徐霞客肖像，不是他旅行时拍的照片。要了解他怎样观察山川，需要结合游记与研究资料。',[X],330,'明代人物 · 后世肖像作品')
scene_find(c['steps'][2],[('look','左边指向河与桥的观察',.055,.24,.31,.21),('note','右边画下所见的本子',.65,.61,.245,.23)],[('look','哪里正在观察眼前的河与桥？','look','先看现场，留意桥与水的具体关系。','这里在画记录，再找看着河与桥的人。','再找留下观察记录的地方'),('note','哪里把所见画下来，留给以后看？','note','本子留下了可以回看的线索。','这里在观察，记录在另一边的本子上。','离开前怎样留下这个发现')])
done(c,a,'ming-xu-xiake-notebook',['指着练习图，说明观察和记录是两个相连的动作。','在家选门和桌子两个熟悉的东西，先看位置，再画给家人看，并说明这是谁今天画的。'],'只做安全熟悉环境的观察；不安排临水攀爬，不编真实日记引文，不宣称画像完全还原容貌。')
# 7 承德
id='cn-ancient-08-03-frontiers-unity';a='qing-chengde-meeting-v1'
c=base(id,'承德山庄里，为什么要会见来客？','这里有山水，也有会见和办事。来自不同地区的人来到承德，小伙伴去看大家怎样解释意思、记录事情。','清代承德不只是避暑的地方，也用于处理政务、会见不同地区的来客。沟通与联系，是了解多民族国家历史的一条线索。','清代承德的来客、翻译与记录者',[C,M],'现代园林照片不等于清代会见现场。故事角色和会谈为虚构，不按衣服判断具体族群，不声称复原某位首领某次会见。会见、礼仪只是清代处理不同地区事务的一部分，各地制度有差异，历史中也存在战争和冲突，不能从一幅和睦图推出始终如此。','相互说明、留下记录，让联系继续。')
c['steps']=[step('从承德的园林走进清朝','这是今天的承德避暑山庄。它在清朝开始建造。皇帝在这里避暑，也处理政务、会见来自不同地区的来客。小伙伴来看看，山水之外还有什么历史。','清朝开始建造的山庄，带我们去哪？','到清朝，看看山庄里的会见与政务。','明朝在前，避暑山庄开始建造在清朝。','听听这里为什么需要会见',[C],kind='timeline',options=[era('清朝','1703年开始建造','later',True,'calendar'),era('明朝','1368—1644年','later',False,'calendar')],lead='承德避暑山庄开始建造在清朝，我们去看会见与政务。'),step('山水之间，也要商量事情','清代皇帝在承德会见不同地区的首领和来客，处理政务，保持联系。语言和习惯可能不同，需要解释，也要留下记录。历史上有交往，也有冲突，不能只看一幅和睦的画。','会见让不同地区发生联系','沟通是联系的一部分，历史还要看更多材料。','可以再听一遍。','找找解释与记录的工作',[C,M],kind='look-listen',asset=a,display='会见、处理政务、保持联系。\n一幅故事图，不能代表全部历史。'),step('把意思说清，把事情记下','故事中的来客正在说明事情，中间有人帮助解释，旁边有人记录。先找帮助双方理解的工作，再找留下记录的工作。','谁正在帮助双方解释意思？','解释与记录，让会见能够继续。','看看谁面对双方，谁把笔落在纸上。','一句话没听懂，先怎么办',[C],kind='scene-find',asset=a),step('意思还没听懂，先做哪件事','来客刚说完一件事，另一边还没听懂。记录的人也拿起了笔。为了把这件事说清楚，此刻先做什么？','一句话没听懂，先请谁帮助？','先解释清楚，再确认怎样记录和办理。','记录能留下事情，但要先弄懂意思。','把会见放回历史里',[C],options=[card('请中间的人帮助解释',a,[630,175,320,510,1536,1024],True),card('请桌边的人先写记录',a,[1300,245,236,340,1536,1024],False)],asset=a),step('园林之外，看见联系','清代承德的会见和政务，留下了不同地区交往的历史。维系国家联系，还有许多制度和具体工作，各地情况也不同。今天看园林，再读文献，才能了解不只山水的故事。','建筑留下地点，文献帮助解释','会见与办事，让我们看见人与地方的联系。','可以再听一遍。','带着会见的发现回家',[C,M],kind='look-listen',asset=a,display='不是只看风景。\n还要问：谁来这里，为什么来？')]
c['steps'][0]['inspection']=ins('chengde-mountain-resort-current-view','这是2006年的园林照片，不是清代会见现场。山庄留下了地点，清代如何处理政务、会见来客，还需要文献帮助说明。',[C],325,'清代始建园林 · 2006年现状照片')
scene_find(c['steps'][2],[('explain','中间帮助解释的工作',.43,.37,.17,.24),('record','右侧桌边记录的工作',.86,.40,.13,.14)],[('explain','谁正在帮助双方解释意思？','explain','意思说清楚，双方才能继续沟通。','这里在写记录，再找面对双方的人。','再找把事情记录下来的地方'),('record','哪里正把听到的事情写下来？','record','记录把会见中的事情留了下来。','那里在解释，再找桌上的笔和纸。','如果还有一句话没听懂')])
done(c,a,'ming-qing-frontiers-unity',['在图里分别找解释与记录，说明它们解决什么问题。','家人说一个今天的小计划，你先用自己的话解释一遍，再画个符号记下来。'],'不把外貌服装当作族属测验，不说清代各地区治理完全相同；儿童主旨为会见、政务与联系。','qing-friends-reunion-v2')
# 8 广州与世界
id='cn-ancient-08-05-late-crisis';a='qing-canton-trade-v1'
c=base(id,'广州有商船，世界又发生了什么？','旧画里商船来往，码头上有人交涉、查验和搬货。海的另一边，机器也在变化。小伙伴把这两条线索放在一起看。','清代广州仍有海外贸易，但西洋海上贸易受到口岸等限制。同期英国蒸汽动力不断改良，工业变化带来新的世界局势。','广州贸易中的劳动者与改良蒸汽机的瓦特等工程师',[H,Q,W,WI,M],'约1780广州商馆画与1822刊瓦特1782技术说明图不是同年同地。1757后的口岸限制针对西洋海上贸易，不等于所有外国人或全部清代贸易只准广州。十三行不是始终十三家。瓦特改良而非发明第一台蒸汽机；学具省略气门等，不复原瓦特整机；不以单一原因解释后来危机，本章截至近代前夜不表示清朝止于1840。','看见往来与限制，也看看世界怎样变化。')
c['steps']=[step('从一幅商馆旧画走进清朝','这幅约1780年的画表现广州商馆与船只，那时中国是清朝。它不是照片，却留下贸易往来的图像线索。既然有商船，为什么还说当时贸易受到限制呢？','约1780年的广州，处在哪一朝？','到清朝广州，看看往来和规矩。','明朝更早，约1780年已是清朝。','听听贸易怎样受到限制',[Q,H],kind='timeline',options=[era('清朝','约1780年','later',True,'calendar'),era('明朝','1368—1644年','later',False,'calendar')],lead='约1780年是清朝，这幅旧画描绘广州的商船和商馆。'),step('有往来，也有严格限制','1757年以后，西洋商船来华贸易被限定在广州。商人还要按规定交涉、查验和缴税。这不是完全没有海外往来，也不是所有地方、所有人的贸易都只能在广州。','商船往来，要经过规定的手续','看见贸易存在，也看见它受到的限制。','可以再听一遍。','去码头找两种工作',[Q,H],kind='look-listen',asset=a,display='西洋商船贸易集中广州，受到限制。\n并不等于全部海外往来都断了。'),step('货物移动，也要有人查验','故事里的码头，有人核对货物和清单，有人搬运货箱，还有商人在交涉。先找查验，再找搬运，看一批货怎样经过不同人的工作。','哪里正在核对货物和清单？','货物来往，连着手续和劳动。','看看桌上清单与手里货箱的不同。','海的另一边，机器怎样变化',[H,Q],kind='scene-find',asset=a),step('海的另一边，机器在变化','大致同一时期，英国的蒸汽机不断得到改良，瓦特作了重要贡献，机器为工场提供动力。我们用简化学具看看：活塞来回移动，怎样带着轮子继续转？','活塞来回，轮子怎样继续转？','来回运动带动转轮，可以继续带动机器。','再看活塞与轮子怎样连着。','把两条历史线索连起来',[W,WI],kind='history-lab',asset=a),step('往来、限制，还有新的变化','清代广州有海外贸易，也有严格限制。海的另一边，蒸汽动力等工业变化正在发展。后来中国面临新的局势，还有许多原因要了解；不能只凭一幅热闹港口画，就说全部情况。','历史要把不同线索放在一起看','港口的往来，与世界变化一起观察。','可以再听一遍。','带着两条线索回到时间河',[Q,W,WI,M],kind='look-listen',asset=a,display='广州：有贸易，也有严格限制。\n海外：工业与机器正在变化。')]
c['steps'][0]['inspection']=ins('canton-factories-circa-1780-painting','这是一幅约1780年的广州商馆画，不是照片。看看岸边建筑与船只就好；不能用旗帜或船的数量推算全部贸易。',[Q,H],310,'清代约1780年 · 历史绘画')
scene_find(c['steps'][2],[('check','左边桌上核对清单的地方',.07,.25,.27,.18),('carry','右边搬运货箱的工作',.815,.37,.18,.28)],[('check','哪里正在核对货物和清单？','check','贸易要经过查验等规定手续。','那里在搬货，再找桌上的清单。','再找把货箱搬过去的工作'),('carry','谁正在把货箱搬到码头？','carry','货物运输也靠许多人的劳动。','那里在查验，再找拿着货箱的人。','去看看同期的机器变化')])
c['steps'][3]['interaction']['lab']={'kind':'engine','stages':[{'label':'看看第一程怎样带动轮子','narration':'活塞走向另一边，连杆带着轮子转了半圈。'},{'label':'再看回来时轮子怎样转','narration':'活塞回来了，轮子继续同向转动，合起来转完一圈。'}]}
c['steps'][3]['inspection']=ins('watt-steam-engine-1822-engraving','这是1822年刊出的技术图，依据瓦特1782年的说明，不是广州码头现场。瓦特改良蒸汽机；旁边的学具只帮助看往复与转动，不是这台机器的完整复原。',[W,WI],320,'1822年刊图 · 依据瓦特1782年说明');c['steps'][3]['inspection']['placement']='supporting'
done(c,a,'ming-qing-late-crisis',['先指码头上的查验与搬运，说说有贸易为什么仍有规矩和限制。','一只手来回移动，另一只手画圆，模仿学具两种运动，再说机器变化发生在另一条历史线索里。'],'不使用真实蒸汽或热源；区别抽象连杆学具与历史整机。不同地区的发展不做文明排名，也不以一项政策概括全部危机原因。','qing-friends-reunion-v2')
